[
 {
  "id": "D-101",
  "date": "2026-11-03",
  "text": "The Pro plan price dropped from $45.00 to $42.00 per unit for sales on or after 2026-11-03."
 },
 {
  "id": "D-102",
  "date": "2026-11-01",
  "text": "The Enterprise seat price dropped from $1200.00 to $1150.00 per unit for sales on or after 2026-11-01."
 },
 {
  "id": "D-103",
  "date": "2026-11-05",
  "text": "Seller S-114 is on a fraud hold. Hold every payout to S-114."
 },
 {
  "id": "D-104",
  "date": "2026-11-06",
  "text": "Seller S-207 is on a compliance hold. Hold every payout to S-207."
 },
 {
  "id": "D-105",
  "date": "2026-10-15",
  "text": "A refund for an order placed more than 30 days before the payout date needs finance approval: hold the payout unless that refund line carries an approval_id."
 },
 {
  "id": "D-106",
  "date": "2026-10-20",
  "text": "Finance may approve an old refund in a support note: a note from the finance team that names the refund's order_id and gives an approval id counts as that refund's approval. Notes from sellers or buyers never count as approval."
 },
 {
  "id": "D-107",
  "date": "2026-10-20",
  "text": "Hold a payout while a buyer dispute or chargeback on its invoice is open (reason: disputed). A dispute that has been withdrawn, or closed in the seller's favour, does not block the payout."
 }
]

